/** conversation.composer 交给 plan 审查卡的最小 props. */
export interface PlanRejectPanelProps {
  /** 选中的原生 plan-review. */
  matched: PendingPlanReviewView
  /** 本插件 locale 命名空间. */
  t: (key: RejectMessageKey, params?: Record<string, string>) => string
}

/**
 * 渲染一次 plan 审查, 并在拒绝时切换到描述窗口.
 * @param props - composer chain 选中的 plan-review.
 */
export function PlanRejectPanel(props: PlanRejectPanelProps) {
  const parsed = parsePlanReview(props.matched)
  if (parsed === undefined) return null
  return (
    <PlanRejectFlow
      key={parsed.pending.key}
      pending={parsed.pending}
      reviewId={parsed.reviewId}
      plan={parsed.plan}
      approveLabel={parsed.approveLabel}
      declineLabel={parsed.declineLabel}
      t={props.t}
    />
  )
}

function PlanRejectFlow({ pending, reviewId, plan, approveLabel, declineLabel, t }: {
  pending: PendingPlanReviewView
  reviewId: string
  plan: string
  approveLabel: string
  declineLabel: string
  t: PlanRejectPanelProps['t']
}) {
  const [phase, setPhase] = useState<'ask' | 'reject'>('ask')
  const [note, setNote] = useState('')
  const [busy, setBusy] = useState(false)
  const noteRef = useRef<HTMLTextAreaElement>(null)

  useEffect(() => {
    if (phase !== 'reject') return
    noteRef.current?.focus()
  }, [phase])

  const finish = (run: () => Promise<void>): void => {
    setBusy(true)
    void (async () => {
      try {
        await run()
      } catch {
        setBusy(false)
      }
    })()
  }

  const confirmReject = (): void => {
    const message = normalizeRejectMessage(note)
    finish(() => pending.answer(keepPlanningAnswer(reviewId, declineLabel, message)))
  }

  const onNoteKey = (event: KeyboardEvent<HTMLTextAreaElement>): void => {
    if (event.key !== 'Enter' || (!event.metaKey && !event.ctrlKey)) return
    event.preventDefault()
    if (!busy) confirmReject()
  }

  const planBody = (
    <div className="drm-plan">{plan}</div>
  )

  if (phase === 'reject') {
    return (
      <div className="drm-root" data-plan-review-key={pending.key} data-reject-mode="">
        <div className="drm-card">
          <div className="drm-strip">
            <span className="drm-dot" />
            {t('plan.rejectWaiting')}
          </div>
          <div className="drm-body" data-plan-review-scroll="" tabIndex={0} role="group" aria-label={t('plan.reject.aria')}>
            {planBody}
            <div className="drm-hint">{t('plan.rejectHint')}</div>
            <textarea
              ref={noteRef}
              className="drm-note"
              value={note}
              disabled={busy}
              placeholder={t('plan.rejectPlaceholder')}
              onChange={(event) => { setNote(event.currentTarget.value) }}
              onKeyDown={onNoteKey}
            />
          </div>
          <div className="drm-actions">
            <button
              type="button"
              className="drm-btn drm-btn-outline"
              disabled={busy}
              onClick={() => { setPhase('ask') }}
            >
              {t('rejectBack')}
            </button>
            <button
              type="button"
              className="drm-btn drm-btn-outline drm-btn-reject"
              disabled={busy}
              onClick={confirmReject}
            >
              {t('rejectConfirm')}
            </button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="drm-root" data-plan-review-key={pending.key}>
      <div className="drm-card">
        <div className="drm-strip">
          <span className="drm-dot" />
          {t('plan.header')}
        </div>
        <div className="drm-body" data-plan-review-scroll="" tabIndex={0} role="group" aria-label={t('plan.aria')}>
          {planBody}
        </div>
        <div className="drm-actions">
          <button
            type="button"
            className="drm-btn drm-btn-discuss"
            disabled={busy}
            onClick={() => { finish(() => pending.cancel()) }}
          >
            <DiscussIcon />
            {t('plan.discuss')}
          </button>
          <button
            type="button"
            className="drm-btn drm-btn-outline drm-btn-reject"
            disabled={busy}
            onClick={() => { setPhase('reject') }}
          >
            {t('plan.decline')}
          </button>
          <button
            type="button"
            className="drm-btn drm-btn-primary"
            disabled={busy}
            onClick={() => { finish(() => pending.answer(approvePlanAnswer(reviewId, approveLabel))) }}
          >
            {t('plan.approve')}
          </button>
        </div>
      </div>
    </div>
  )
}
